<script setup>
import {ref,reactive,computed,watch,nextTick,onMounted,onBeforeUnmount} from 'vue';
import {Button,Tab,Tabs,Tag,Field,Popup,Picker,RadioGroup,Radio,Progress,Collapse,CollapseItem,Cell,CellGroup} from 'vant';
import 'vant/es/button/style';import 'vant/es/tabs/style';import 'vant/es/tab/style';import 'vant/es/tag/style';import 'vant/es/field/style';import 'vant/es/popup/style';import 'vant/es/picker/style';import 'vant/es/radio-group/style';import 'vant/es/radio/style';import 'vant/es/progress/style';import 'vant/es/collapse/style';import 'vant/es/collapse-item/style';import 'vant/es/cell/style';import 'vant/es/cell-group/style';
const props=defineProps({controller:{type:Object,required:true}}),m=ref(props.controller.model),a=props.controller.actions;
const stop=props.controller.subscribe(value=>{m.value=value;});const choice=ref(),search=ref(''),opened=ref([]),picker=ref(null),pickerValues=ref([]),stage=ref(),board=ref(),detail=ref(),heading=ref();
const error=ref('');function run(name,...args){try{error.value='';a[name](...args);}catch(e){error.value=e.message;}}
const columns=computed(()=>{const k=picker.value;if(k==='chapter')return m.value.chapters.map(c=>({text:`${c.term==='upper'?'上册':'下册'} · 第${c.number}章 ${c.title}`,value:c.id}));if(k==='scope')return [{text:'1 层',value:'1'},{text:'2 层',value:'2'},{text:'全部先修',value:'all'}];if(k==='range')return [{text:'本章及先修',value:'chapter'},{text:'全部章节',value:'year'}];if(k==='target')return [{text:`${m.value.chapter.title}整章评测（${m.value.targets.length*2}题）`,value:'chapter'},...m.value.targets.map(n=>({text:n.title+'（2题）',value:n.id}))];return (k==='panNode'?m.value.panorama.nodes:m.value.availableNodes).map(n=>({text:n.title,value:n.id}));});
function openPicker(key){picker.value=key;pickerValues.value=[key==='chapter'?m.value.chapter.id:key==='panNode'||key==='node'?m.value.selected.id:m.value[key]];}
function confirmPicker({selectedValues}){const key=picker.value;picker.value=null;run(key==='node'||key==='panNode'?'locate':key,selectedValues[0]);if(key==='panNode')nextTick(center);}
function locate(id,centered=false){run('locate',id);if(centered)nextTick(center);else if(m.value.mode!=='panorama')nextTick(()=>detail.value?.scrollIntoView({block:'nearest'}));}
function submit(){if(choice.value===undefined){error.value='请选择一个答案，或选择“暂时不会 / 不确定”。';return;}run('answer',choice.value==='unsure'?null:choice.value);choice.value=undefined;nextTick(()=>heading.value?.focus());}
watch(()=>m.value.question?.id,()=>{choice.value=undefined;});
const view=reactive({s:1,x:0,y:0}),transform=computed(()=>`translate(${view.x} ${view.y}) scale(${view.s})`);
const size=()=>({w:stage.value?.clientWidth||600,h:stage.value?.clientHeight||540});
function fit(){if(!stage.value)return;const {w,h}=size(),p=m.value.panorama;view.s=Math.max(.05,Math.min(1,(w-28)/p.width,(h-28)/p.height));view.x=(w-p.width*view.s)/2;view.y=(h-p.height*view.s)/2;}
function zoom(s,cx,cy){const {w,h}=size();cx??=w/2;cy??=h/2;s=Math.min(2.5,Math.max(.05,s));const x=(cx-view.x)/view.s,y=(cy-view.y)/view.s;Object.assign(view,{s,x:cx-x*s,y:cy-y*s});}
function center(id=m.value.selected.id){const n=m.value.panorama.nodes.find(n=>n.id===id);if(!n)return;const {w,h}=size(),s=Math.max(.85,view.s);Object.assign(view,{s,x:w/2-(n.x+n.width/2)*s,y:h/2-(n.y+n.height/2)*s});}
const pointers=new Map();let drag=null,pinch=null,dragged=false,pick=null;
function point(e){const r=stage.value.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
function pinchData(){const [a,b]=[...pointers.values()];return {x:(a.x+b.x)/2,y:(a.y+b.y)/2,d:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))};}
function down(e){if(e.button!==0)return;pointers.set(e.pointerId,point(e));stage.value.setPointerCapture(e.pointerId);if(pointers.size===1){drag={...point(e),view:{...view}};dragged=false;pick=e.target.closest('[data-pan-node]')?.dataset.panNode||null;}else if(pointers.size===2){pinch={...pinchData(),view:{...view}};dragged=true;pick=null;}}
function move(e){if(!pointers.has(e.pointerId))return;const p=point(e);pointers.set(e.pointerId,p);if(pointers.size>=2&&pinch){const q=pinchData(),s=Math.max(.05,Math.min(2.5,pinch.view.s*q.d/pinch.d));Object.assign(view,{s,x:q.x-(pinch.x-pinch.view.x)/pinch.view.s*s,y:q.y-(pinch.y-pinch.view.y)/pinch.view.s*s});}else if(drag){const dx=p.x-drag.x,dy=p.y-drag.y;if(Math.hypot(dx,dy)>5)dragged=true;if(dragged){view.x=drag.view.x+dx;view.y=drag.view.y+dy;}}}
function up(e){const id=e.type==='pointerup'&&!dragged&&pointers.size===1?pick:null;pointers.delete(e.pointerId);pinch=null;drag=pointers.size===1?{...[...pointers.values()][0],view:{...view}}:null;pick=null;if(id)locate(id);}
function wheel(e){if(!e.ctrlKey)return;e.preventDefault();const p=point(e);zoom(view.s*Math.exp(-e.deltaY*.008),p.x,p.y);}
function keydown(e){if(e.target.closest('[data-pan-node]')&&['Enter',' '].includes(e.key)){e.preventDefault();locate(e.target.closest('[data-pan-node]').dataset.panNode);return;}if(e.key==='Home'){e.preventDefault();fit();}else if(['+','=','-'].includes(e.key)){e.preventDefault();zoom(view.s*(e.key==='-'?1/1.25:1.25));}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();view.x+=e.key==='ArrowLeft'?48:e.key==='ArrowRight'?-48:0;view.y+=e.key==='ArrowUp'?48:e.key==='ArrowDown'?-48:0;}}
function rows(title){const out=[''];let used=0;for(const ch of title){const n=/[\x00-\x7f]/.test(ch)?7:13;if(used+n>154){out.push('');used=0;}out[out.length-1]+=ch;used+=n;}return out;}
const edges=ref([]);function draw(){if(!board.value)return;const r=board.value.getBoundingClientRect(),points=new Map();board.value.querySelectorAll('[data-graph-node]').forEach(el=>{const b=el.getBoundingClientRect();points.set(el.dataset.graphNode,{left:b.left-r.left,right:b.right-r.left,y:b.top+b.height/2-r.top});});edges.value=m.value.graphEdges.filter(e=>points.has(e.from)&&points.has(e.to)).map(e=>{const a=points.get(e.from),b=points.get(e.to),forward=a.right<b.left,mid=forward?(a.right+b.left)/2:Math.max(a.right,b.right)+9;return {...e,path:`M${a.right},${a.y} C${mid},${a.y} ${mid},${b.y} ${forward?b.left-2:b.right+2},${b.y}`};});}
let observer;async function observe(){await nextTick();observer?.disconnect();if(stage.value){observer?.observe(stage.value);fit();}if(board.value){observer?.observe(board.value);draw();}}
watch(()=>[m.value.mode,m.value.scope,m.value.selected?.id,m.value.range],async (value,old)=>{await nextTick();if(value[0]!==old?.[0]||value[3]!==old?.[3])observe();else draw();});
onMounted(()=>{observer=new ResizeObserver(()=>{draw();if(stage.value)fit();});observe();});
onBeforeUnmount(()=>{stop();observer?.disconnect();pointers.clear();});
</script>

<template>
 <main class="student-knowledge workspace" :class="{'is-panorama':m.mode==='panorama'}">
  <template v-if="m.kind==='error'"><h1>{{ m.title }}</h1><Button tag="a" :href="m.backHref">返回目录</Button></template>
  <template v-else>
   <nav class="student-knowledge-nav"><Button tag="a" :href="m.backHref" icon="arrow-left">{{ m.subjectName }}目录</Button><Button tag="a" href="index.html" class="brand"><img :src="'brand-logo.webp'" alt="" width="32" height="32">逆流</Button></nav>
   <header class="student-k-heading"><div><p class="student-k-eyebrow">{{ m.subject==='physics'?'苏科版2025年第4版':'苏科版' }} · 八年级{{ m.chapter.term==='upper'?'上':'下' }}册 · 第{{ m.chapter.number }}章</p><h1>先找到卡住的那一步。</h1></div><span class="chapter-number">{{m.chapter.number}}</span></header><p class="scope-note"> </p>
   <div class="student-k-toolbar"><label>选择章节</label><Button @click="openPicker('chapter')">{{m.chapter.term==='upper'?'上册':'下册'}} · 第{{m.chapter.number}}章 {{ m.chapter.title }} <span aria-hidden="true">⌄</span></Button><Button tag="a" :href="m.studyHref">回本章学习</Button><Button tag="a" :href="m.summaryHref">单元总结</Button></div>
   <Tabs :active="m.mode" @update:active="run('mode',$event)"><Tab name="graph" title="知识图谱"/><Tab name="panorama" title="全景图谱"/><Tab name="diagnosis" title="先测一下"/></Tabs>
   <p v-if="m.notice" role="status" class="student-k-notice">{{ m.notice }}</p><p v-if="error" role="alert" class="student-k-notice">{{ error }}</p>
   <div :class="{'student-k-graph-layout':m.mode==='graph'}">
   <template v-if="m.mode==='graph'">
    <section class="student-k-panel"><div class="student-k-row"><h2>知识怎样相连</h2><Button size="small" @click="openPicker('scope')">先修范围：{{ m.scope==='all'?'全部':m.scope+' 层' }}</Button></div><p>点击知识点看详情。箭头从先修点指向后续知识点。</p><p class="student-k-legend"><span><i/>必要先修</span><span><i class="soft"/>辅助关系</span></p>
     <div ref="board" class="student-k-board"><svg class="student-k-lines" aria-hidden="true"><defs><marker id="student-k-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#98aa87"/></marker></defs><path v-for="e in edges" :key="e.from+e.to" :d="e.path" :class="e.strength" marker-end="url(#student-k-arrow)"/></svg><div class="student-k-columns"><div v-for="(column,i) in m.graphNodes" :key="i"><p>{{ ['先修知识','当前知识点','直接后续'][i] }}</p><Button v-for="n in column" :key="n.id" :data-graph-node="n.id" :class="['student-k-node',n.status]" :plain="n.id!==m.selected.id" :type="n.id===m.selected.id?'primary':'default'" :aria-pressed="n.id===m.selected.id" @click="locate(n.id)"><strong>{{ n.title }}</strong><small>{{ n.statusLabel }}{{ n.handwriting?.score!==null&&n.handwriting?.score<80?' · 手写评测':'' }}</small></Button><p v-if="!column.length" class="student-k-muted">{{ i===0?'本图谱未继续拆分先修':'本图谱的终点' }}</p></div></div></div>
     <Button @click="openPicker('node')">快速定位：{{ m.selected.title }}</Button><p class="student-k-muted">颜色与标签参考本轮诊断；有实卷手写评测时，薄弱与不稳优先标出。未作答的先修不会自动算通过。</p>
    </section>
   </template>
   <section v-else-if="m.mode==='panorama'" class="student-k-panel">
    <div class="student-k-row"><h2>{{ m.range==='year'?'全部章节':m.chapter.title }} · 全景图谱</h2><Button @click="openPicker('range')">{{ m.range==='year'?'全部章节':'本章及先修' }}</Button></div><p>{{ m.panorama.nodes.length }} 个知识点 · {{ m.panorama.edges.length }} 条关系。橙框为当前节点，蓝色为关联路径；路径颜色不表示掌握。</p>
    <div class="student-k-toolbar"><Button aria-label="缩小" @click="zoom(view.s/1.25)">−</Button><output aria-label="当前缩放">{{ Math.round(view.s*100) }}%</output><Button aria-label="放大" @click="zoom(view.s*1.25)">＋</Button><Button @click="fit">适合画布</Button><Button @click="center()">定位当前</Button></div>
    <form class="student-k-search" role="search" @submit.prevent="run('search',search);nextTick(()=>center())"><Field v-model="search" type="search" label="搜索知识点" placeholder="输入知识点名称" maxlength="60"/><Button native-type="submit">查找</Button></form><p v-if="m.searchNote" role="status">{{ m.searchNote }}</p><p class="student-k-muted" id="student-k-pan-help">拖动画布移动；双指或按钮缩放。电脑可用 Ctrl＋滚轮；方向键移动，＋/−缩放，Home看全图。</p>
    <div ref="stage" class="student-k-stage" tabindex="0" role="region" aria-label="可拖动缩放的全景知识图谱" aria-describedby="student-k-pan-help" :data-scale="view.s" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @wheel="wheel" @keydown="keydown">
     <svg width="100%" height="100%" role="group" aria-label="知识点及先修连线"><defs><marker id="student-pan-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#8a9daa"/></marker></defs><g :transform="transform"><path v-for="e in m.panorama.edges" :key="e.from+e.to" :d="e.path" :class="['student-pan-edge',e.strength,{'on-path':e.onPath}]" marker-end="url(#student-pan-arrow)"><title>{{ e.label }}</title></path>
      <g v-for="n in m.panorama.nodes" :key="n.id" :data-pan-node="n.id" :class="['student-pan-node',n.relation]" :transform="`translate(${n.x} ${n.y})`" role="button" tabindex="0" :aria-pressed="n.id===m.selected.id" :aria-label="`${n.title}，${n.group?'第'+n.group+'章':'基础先修'}，${n.statusLabel}`" @click="$event.detail===0 && locate(n.id)" @focus="!$event.sourceCapabilities && center(n.id)"><title>{{ n.title }} · {{ n.section }}</title><rect :width="n.width" :height="n.height" rx="9"/><text text-anchor="middle" :x="n.width/2"><tspan v-for="(line,i) in rows(n.title)" :key="i" :x="n.width/2" :y="rows(n.title).length===1?29:23+i*17">{{ line }}</tspan></text><text class="student-pan-meta" :x="n.width/2" y="62" text-anchor="middle">{{ n.group?'第'+n.group+'章':'基础先修' }} · {{ n.statusLabel }}</text></g></g></svg>
    </div><div class="student-k-row"><p aria-live="polite">当前：<strong>{{ m.selected.title }}</strong></p><Button @click="detail?.scrollIntoView({block:'start'})">查看复习卡 ↓</Button></div><Button @click="openPicker('panNode')">快速定位</Button><p class="student-k-muted">诊断标签沿用当前章节的本轮记录，不合并其他章节存档。</p>
   </section>
   <section v-if="m.mode!=='diagnosis'" ref="detail" class="student-k-panel student-k-detail">
    <p class="student-k-eyebrow">{{ m.selected.section }}</p><h2>{{ m.selected.title }}</h2><Tag plain>{{ m.selected.statusLabel }}</Tag>
    <section v-if="m.selected.handwriting" data-handwriting-evidence><h3>实卷手写评测 · {{ m.handwritingStatus }}{{ m.selected.handwriting.score===null?'':' · '+m.selected.handwriting.score+'/100' }}</h3><p>{{ m.selected.handwriting.feedback }}</p><Button tag="a" :href="m.handwritingHref">重做这道实卷题</Button><p class="student-k-muted">本题通过不等于课程达标；薄弱、不稳按当前原稿的最近有效知识点评测更新。</p></section>
    <h3>学会后应能做到</h3><p>{{ m.selected.criterion }}</p><h3>为什么需要这些先修</h3><ul v-if="m.relations.length"><li v-for="r in m.relations" :key="r.from"><Button plain size="small" @click="locate(r.from)">{{ r.title }}</Button> · {{ r.strength==='hard'?'必要':'辅助' }}<p>{{ r.reason }}</p></li></ul><p v-else class="student-k-muted">这是本图谱的基础点，尚未向前细分。</p><h3>复习卡</h3><div class="student-k-review">{{ m.selected.review }}<p>{{ m.selected.example }}</p></div><p class="student-k-muted">{{ m.selected.source }}。关系强弱为教学设计，尚未用学生数据校准。</p><div class="student-k-toolbar"><Button type="primary" @click="run('prepare',m.selected.id)">诊断这个知识点</Button><Button v-if="m.courseHref" tag="a" :href="m.courseHref">打开课程</Button><Button v-if="m.hasSession" @click="run('mode','diagnosis')">回到本轮诊断</Button></div>
   </section>
   <section v-else class="student-k-panel">
    <template v-if="m.screen==='setup'"><p class="student-k-eyebrow">定位薄弱环节 · 每点固定两题</p><h2>从哪里开始检查？</h2><ol><li>选择整章或一个知识点，每个目标固定两题。</li><li>所有人按相同顺序作答，答题中不提示对错或诊断标签。</li><li>全部提交后统一查看诊断报告与逐题解析。</li></ol><Button @click="openPicker('target')">选择目标：{{ m.target==='chapter'?m.chapter.title+'整章':m.targets.find(n=>n.id===m.target)?.title }}</Button><p>遇到不熟悉的题，可以选择“暂时不会”。</p><p v-if="m.hasSession" class="student-k-notice">已有本轮记录：作答 {{ m.asked }} 题。{{ m.canResume?'可以继续上次诊断。':'可查看本轮结果。' }}新开诊断会替换这份诊断记录。</p><div class="student-k-toolbar"><Button type="primary" @click="run('start')">{{ m.hasSession?'新开一次诊断':'开始诊断' }}</Button><Button v-if="m.hasSession" @click="run('resume')">{{ m.canResume?'继续上次诊断':'查看本轮结果' }}</Button></div></template>
    <template v-else-if="m.screen==='question'"><p>已完成 {{ m.asked }} 题 / 共 {{ m.limit }} 题</p><Progress :percentage="m.asked/m.limit*100" :show-pivot="false"/><h2 ref="heading" tabindex="-1">{{ m.question.prompt }}</h2><form @submit.prevent="submit"><RadioGroup v-model="choice" aria-label="选择一个答案"><CellGroup><Cell v-for="(option,i) in m.question.options" :key="i" :title="'ABCD'[i]+' '+option" clickable @click="choice=i"><template #right-icon><Radio :name="i" :aria-label="option"/></template></Cell><Cell title="暂时不会 / 不确定" clickable @click="choice='unsure'"><template #right-icon><Radio name="unsure" aria-label="暂时不会 / 不确定"/></template></Cell></CellGroup></RadioGroup><p aria-live="polite">{{ m.feedback }}</p><div class="student-k-toolbar"><Button type="primary" native-type="submit">{{ m.asked+1===m.limit?'完成评测，查看诊断报告':'提交，继续作答' }}</Button><Button :disabled="!m.asked" @click="run('undo')">撤销上一题</Button></div></form></template>
    <template v-else-if="m.report"><p class="student-k-eyebrow">本轮学习线索 · 不是掌握认证</p><h2 ref="heading" tabindex="-1">知道下一步该练什么。</h2><p>已作答 {{ m.asked }} / 最多 {{ m.limit }} 题。{{ m.report.limitReached?'已到题量上限，尚有内容未确认。':m.report.closed?'本轮提前结束，结论只基于已作答部分。':'本轮目标的检查路径已结束；未测先修仍保留未测。' }}</p><div class="student-k-stats"><div v-for="group in m.report.groups" :key="group.key"><strong>{{ group.count }}</strong><span>{{ group.label }}</span></div></div><p v-if="m.report.credit" class="student-k-notice">本轮图谱诊断正确率 {{ (Object.values(m.report.credit).reduce((a,b)=>a+b,0)/m.report.targets.length*100).toFixed(1) }}%。</p><p v-else>这是旧版初筛记录；新开一次评测并全部完成后，才能计入图谱诊断排行榜分项。</p><p v-if="m.report.groups.find(g=>g.key==='pending').count" class="student-k-notice">待复测：{{ m.report.evidence.filter(n=>n.status==='pending').map(n=>n.title).join('、') }}。每点只有一题未通过，证据不足，不能判为薄弱。</p>
     <h3>可能卡住的基础环节</h3><div v-for="r in m.report.roots" :key="r.id" class="student-k-review"><h3>{{ r.title }}</h3><p>两题未通过（包含“暂时不会”）。{{ r.uncertain.length?'它的必要先修“'+r.uncertainTitles.join('、')+'”尚未全部初筛通过，原因可能还在更前面。':'本试点中没有更前的已确认薄弱先修；仍只是候选线索。' }}</p><Button @click="locate(r.id)">看关系与复习卡</Button></div><p v-if="!m.report.roots.length">本轮没有确认的薄弱基础点。初筛通过不等于掌握；待复测和未测部分仍需保留。</p><h3>建议复习顺序</h3><ol v-if="m.report.path.length"><li v-for="n in m.report.path" :key="n.id"><Button @click="locate(n.id)">{{ n.title }} · {{ n.statusLabel }} · 复习</Button></li></ol><p v-else>暂未形成补学路径。可继续原课程；若仍有疑问，单独诊断相关先修点。</p><p v-if="m.report.soft.length">另可检查辅助点：<Button v-for="n in m.report.soft" :key="n.id" @click="locate(n.id)">{{ n.title }}</Button>辅助关系不自动触发回溯，也不推断为薄弱。</p><p>复习后回测原目标：{{ m.report.targets.join('、') }}。新一轮仍只作初筛。</p><h3>逐点证据与解析</h3><p>只根据直接作答给标签。未作答的先修点不会由后续题的结果代推。</p><Collapse v-model="opened"><CollapseItem v-for="n in m.report.evidence" :key="n.id" :name="n.id" :title="`${n.title} · ${n.statusLabel} · ${n.attempts.length} 题`"><div v-for="answer in n.attempts" :key="answer.qid"><strong>{{ answer.prompt }}</strong><p>你的选择：{{ answer.chosen }} · {{ answer.correct?'通过':'未通过' }}</p><p>参考答案：{{ answer.answer }}<br>{{ answer.explanation }}</p></div><p v-if="!n.attempts.length">本轮没有直接作答证据。未测不表示会，也不表示不会。</p><Button @click="locate(n.id)">查看知识点</Button></CollapseItem></Collapse><div class="student-k-toolbar"><Button type="primary" @click="run('retry')">复习后，回测原目标</Button><Button @click="run('newTarget')">换个目标</Button><Button :disabled="!m.asked" @click="run('undo')">撤销最后一题</Button><Button v-if="m.canResume" @click="run('continue')">继续尚未做完的题</Button><Button tag="a" :href="m.studyHref">回课程</Button></div><p class="student-k-muted">本轮涉及 {{ m.report.order.length }} 个目标及先修点；未作整章或全年掌握判断。</p>
    </template>
   </section>
   </div>
   <Popup :show="!!picker" position="bottom" round closeable close-icon="cross" :close-on-click-overlay="true" @update:show="picker=$event?picker:null"><div class="student-k-picker"><Picker v-model="pickerValues" :title="'选择'+({chapter:'章节',scope:'先修范围',range:'查看范围',target:'评测目标',node:'知识点',panNode:'知识点'}[picker]||'')" :columns="columns" :show-toolbar="false"/><Button type="primary" block @click="confirmPicker({selectedValues:pickerValues})">确定</Button></div></Popup>
  </template>
 </main>
</template>

